 private suspend fun copyHistory(from:LearningStore,to:LearningStore,id:String){var after="";do{val(rows,next)=from.historyPage(id,after);to.remember(rows);after=next}while(after.isNotBlank())}
 @Test fun offlineChainsAndConcurrentChanges()=runBlocking<Unit>{
  val a=LearningStore(app,"018-a-${uid()}");val b=LearningStore(app,"018-b-${uid()}")
  try{val q=a.put("question",payload(Question(title="合成离线验收",scope="math")));b.ingest(q);repeat(10){b.editUser(q.id,buildJsonObject{put("title","连续第$it 次")},b.get(q.id)!!.rev)};copyHistory(b,a,q.id);a.ingest(b.get(q.id)!!);assertEquals("连续第9 次",a.get(q.id)!!.payload.s("title"));assertTrue(a.dao.conflicts().isEmpty())
   a.editUser(q.id,buildJsonObject{put("classification","wrong")},a.get(q.id)!!.rev);b.editUser(q.id,buildJsonObject{put("title","离线继续编辑")},b.get(q.id)!!.rev);copyHistory(b,a,q.id);a.ingest(b.get(q.id)!!);assertTrue(a.dao.conflicts().isEmpty());assertEquals("离线继续编辑",a.get(q.id)!!.payload.s("title"));copyHistory(a,b,q.id);b.editUser(q.id,buildJsonObject{put("studentWork","同步中补步骤")},b.get(q.id)!!.rev);b.ingest(a.get(q.id)!!);assertTrue(b.dao.conflicts().isEmpty());assertEquals("wrong",b.get(q.id)!!.payload.s("classification"));assertEquals("同步中补步骤",b.get(q.id)!!.payload.s("studentWork"))
   a.editUser(q.id,buildJsonObject{put("title","真正分叉A")},a.get(q.id)!!.rev);b.editUser(q.id,buildJsonObject{put("title","真正分叉B")},b.get(q.id)!!.rev);copyHistory(b,a,q.id);a.ingest(b.get(q.id)!!);assertTrue(a.dao.conflicts().isNotEmpty())
  }finally{a.db.close();b.db.close()}
 }
 @Test fun archiveAndVerificationDiscardChangedInputs()=runBlocking<Unit>{for(stage in listOf("archive","verify")){
  val store=LearningStore(app,"018-archive-${uid()}");val foreground=AtomicInteger();var changed=false;lateinit var question:SyncRecord;val queued=mutableListOf<String>()
  val fake=object:Provider(app.settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{
   if(role==stage&&!changed){changed=true;store.editUser(question.id,buildJsonObject{put("transcription","a=3")},store.get(question.id)!!.rev)}
   return Turn(if(role=="archive")"""{"title":"旧分析","transcription":"a=2","studentWork":"2","classification":"wrong","concepts":["参数"],"diagnosis":"旧条件结论","solution":"结果为2","errorTypes":[],"evidence":[{"concept":"参数","outcome":"correct","independent":true,"hintLevel":0,"sourceIds":["u"]}]}""" else """{"studentCorrect":true,"correct":true,"notes":"旧核验"}""")
  }}
  val agents=Agents(app,store,fake,MemoryEngine(store),Library(app,store,fake,app.settings,foreground),foreground){task,_,_->queued.add(task)}
  try{question=store.put("question",payload(Question(title="合成任务竞争",scope="math",transcription="a=2")));store.put("message",payload(Message(question.id,"user","我的步骤是2","检查步骤")),"u");store.put("message",payload(Message(question.id,"assistant","先核对条件","检查步骤")));agents.archive(question.id);val q=store.get(question.id)!!;assertEquals("a=3",q.payload.s("transcription"));assertEquals("",q.payload.s("solution"));assertEquals("",q.payload.s("diagnosis"));assertTrue(store.all("evidence").isEmpty());assertTrue("archive" in queued)}finally{store.db.close()}
 }}
 @Test fun longConversationKeepsConditionsAndManualSubject()=runBlocking<Unit>{
  val store=LearningStore(app,"018-conditions-${uid()}");val foreground=AtomicInteger();var prompt="";val fake=object:Provider(app.settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{prompt=messages.first().jsonObject.s("content");onDelta("先按当前条件理解。");return Turn("先按当前条件理解。")}}
  val agents=Agents(app,store,fake,MemoryEngine(store),Library(app,store,fake,app.settings,foreground),foreground){_,_,_->}
  try{val q=store.put("question",payload(Question(title="合成长对话",scope="math",scopeOrigin="user",transcription="a=2")));val source=store.put("message",payload(Message(q.id,"user","参数改成 a=3","轻提示")));store.updateConditions(q.id,source.id,"参数改成 a=3",false)
   repeat(52){store.put("message",payload(Message(q.id,if(it%2==0)"user"else "assistant","历史填充".repeat(300),"轻提示")))}
   assertTrue(agents.send(q.id,"能用傅里叶变换解释这个思路吗？","轻提示"));withTimeout(15000){while(agents.state.value.busy)delay(20)};assertEquals("",agents.state.value.error);assertTrue(prompt.contains("参数改成 a=3"));assertTrue(prompt.contains("a=3"));assertEquals("math",store.get(q.id)!!.payload.s("scope"));assertEquals("signals",store.all("message").last().payload.s("retrievalScope"))
   store.updateConditions(q.id,"temp","如果把 a 换成4呢",true);assertEquals("参数改成 a=3",store.get(q.id)!!.payload.s("effectiveConditions"));assertFalse(StudyContext.conditions(store.get(q.id)!!,"next-turn").contains("换成4"));val hash=StudyContext.inputHash(store.get(q.id)!!,store.messages(q.id));assertTrue(hash.isNotBlank())
   store.editUser(q.id,buildJsonObject{put("effectiveConditions","")},store.get(q.id)!!.rev);assertEquals("",store.get(q.id)!!.payload.s("effectiveConditions"))
  }finally{agents.cancel();store.db.close()}
 }
 @Test fun responseCannotBecomeCompleteAfterInputChanges()=runBlocking<Unit>{val store=LearningStore(app,"018-response-${uid()}");val foreground=AtomicInteger();lateinit var question:SyncRecord;val fake=object:Provider(app.settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{onDelta("旧条件的回答");store.editUser(question.id,buildJsonObject{put("transcription","新条件")},store.get(question.id)!!.rev);return Turn("旧条件的回答")}};val agents=Agents(app,store,fake,MemoryEngine(store),Library(app,store,fake,app.settings,foreground),foreground){_,_,_->};try{question=store.put("question",payload(Question(title="合成前台竞争",scope="math",transcription="旧条件")));assertTrue(agents.send(question.id,"请解释","轻提示"));withTimeout(10000){while(agents.state.value.busy)delay(20)};assertTrue(agents.state.value.error.contains("条件已更新"));assertTrue(store.messages(question.id).none{it.payload.s("role")=="assistant"});assertEquals("interrupted",store.all("message").last().payload.s("completion"))}finally{agents.cancel();store.db.close()}}
 @Test fun duplicateRecordsAndVersions()=runBlocking<Unit>{val store=LearningStore(app,"018-dedup-${uid()}");try{val hash=store.addAsset("合成资料".toByteArray());val doc=Document(title="教材",scope="math",assetIds=listOf(hash));val first=store.importDocument(doc);assertEquals(first.id,store.importDocument(doc.copy(title="别名")).id);assertEquals(1,store.all("document").size);assertNotEquals(first.id,store.importDocument(doc,"independent").id);val newer=store.importDocument(doc.copy(assetIds=listOf(store.addAsset("第二版".toByteArray()))),"version",first.id);assertEquals(first.id,newer.payload.s("versionOf"));assertEquals(hash,store.get(first.id)!!.payload.strings("assetIds").first())}finally{store.db.close()}}
 @Test fun wordFractionsScriptsMatricesAndTablesKeepStructure(){
  val file=File(app.cacheDir,"018-math-${uid()}.docx");val xml="""<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"><w:body><w:p><w:r><w:t>完整公式</w:t></w:r><m:oMath><m:f><m:num><m:r><m:t>1</m:t></m:r></m:num><m:den><m:sSup><m:e><m:r><m:t>x</m:t></m:r></m:e><m:sup><m:r><m:t>2</m:t></m:r></m:sup></m:sSup></m:den></m:f><m:m><m:mr><m:e><m:r><m:t>a</m:t></m:r></m:e><m:e><m:r><m:t>b</m:t></m:r></m:e></m:mr></m:m></m:oMath></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>列一</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>列二</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:body></w:document>"""
  try{ZipOutputStream(file.outputStream()).use{it.putNextEntry(ZipEntry("word/document.xml"));it.write(xml.toByteArray());it.closeEntry()};val extracted=DocumentText.extract(file);assertTrue(extracted.text.contains("\\frac{1}{{x}^{2}}"));assertTrue(extracted.text.contains("\\begin{matrix}a & b"));assertTrue(extracted.text.contains("| 列一 | 列二 |"))}finally{file.delete()}
 }
 @Test fun textRichPdfStillReceivesVisualReconciliationAndRetainsTextOnFailure()=runBlocking<Unit>{
  for(fail in listOf(false,true)){val store=LearningStore(app,"018-pdf-${uid()}");var calls=0;val foreground=AtomicInteger();val fake=object:Provider(app.settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{calls++;if(fail)error("合成视觉失败");return Turn("完整公式 \\(y=\\frac{1}{x^2}\\)。图表横轴时间t，纵轴幅度A，原点为0，曲线递减。正文 enough searchable text.")}}
   try{val pdf=PdfDocument();val page=pdf.startPage(PdfDocument.PageInfo.Builder(600,800,1).create());val paint=Paint().apply{textSize=16f;color=Color.BLACK};repeat(8){page.canvas.drawText("Long paragraph of text with an embedded vector formula and chart $it",20f,40f+it*24,paint)};page.canvas.drawLine(20f,300f,300f,300f,paint);page.canvas.drawLine(20f,300f,20f,200f,paint);pdf.finishPage(page);val bytes=ByteArrayOutputStream().use{pdf.writeTo(it);it.toByteArray()};pdf.close();val doc=store.importDocument(Document(title="合成图文资料.pdf",scope="test",assetIds=listOf(store.addAsset(bytes)),mime="pdf",status="queued"));val library=Library(app,store,fake,app.settings,foreground)
    runCatching{library.process(doc.id)};assertEquals(1,calls);val saved=store.get(doc.id)!!;assertTrue(store.dao.chunks(doc.id,1).isNotEmpty());if(fail){assertEquals("needs_review",saved.payload.s("quality"));assertTrue(saved.payload.s("error").contains("文字已保留"))}else{assertEquals("verified",saved.payload.s("quality"));assertTrue(store.dao.chunks(doc.id,1).any{it.text.contains("frac")})}
   }finally{store.db.close()}
  }
 }
 @Test fun embeddedWordImagesAndExactPdfHighlight()=runBlocking<Unit>{
  val store=LearningStore(app,"018-embedded-${uid()}");val foreground=AtomicInteger();var calls=0;val fake=object:Provider(app.settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{calls++;assertTrue(messages.toString().contains("image_url"));return Turn("图表横轴t(s)，纵轴A(V)，分母为x的平方。")}}
  val file=File(app.cacheDir,"018-embedded-${uid()}.docx")
  try{val bitmap=Bitmap.createBitmap(200,200,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);val png=ByteArrayOutputStream().use{bitmap.compress(Bitmap.CompressFormat.PNG,100,it);bitmap.recycle();it.toByteArray()};ZipOutputStream(file.outputStream()).use{zip->for((name,bytes) in listOf("word/document.xml" to """<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>图文讲义</w:t></w:r><w:drawing/></w:p></w:body></w:document>""".toByteArray(),"word/media/chart.png" to png)){zip.putNextEntry(ZipEntry(name));zip.write(bytes);zip.closeEntry()}}
   val extracted=DocumentText.extract(file);assertEquals(1,extracted.images.size);assertArrayEquals(png,DocumentText.image(file,extracted.images.first()));val doc=store.importDocument(Document(title="内嵌图.docx",scope="test",assetIds=listOf(store.addAsset(file.readBytes())),mime="docx"));Library(app,store,fake,app.settings,foreground).process(doc.id);assertEquals(1,calls);assertEquals(2,store.get(doc.id)!!.payload.i("processed"));assertTrue(store.dao.chunks(doc.id,2).any{it.text.contains("A(V)")})
   val pdf=PdfDocument();val page=pdf.startPage(PdfDocument.PageInfo.Builder(600,800,1).create());page.canvas.drawText("Exact reference phrase in this textbook page",30f,100f,Paint().apply{color=Color.BLACK;textSize=20f});pdf.finishPage(page);val source=File(app.cacheDir,"018-highlight-${uid()}.pdf");try{source.outputStream().use{pdf.writeTo(it)};pdf.close();val rendered=Bitmap.createBitmap(600,800,Bitmap.Config.ARGB_8888);rendered.eraseColor(Color.WHITE);assertTrue(SourceHighlight.draw(app,source,1,rendered,"Exact reference phrase in this textbook page"));assertFalse(SourceHighlight.draw(app,source,1,rendered,"does not exist anywhere"));rendered.recycle()}finally{source.delete()}
  }finally{file.delete();store.db.close()}
 }
 @Test fun liveConditionsAndFormulaRecognition()=runBlocking<Unit>{
  val credentialFile=File(app.filesDir,"live-018-credentials.json");org.junit.Assume.assumeTrue(credentialFile.exists())
  val credentials=try{wire.parseToJsonElement(credentialFile.readText()).jsonObject}finally{credentialFile.delete()}
  val namespace="live018-${uid()}-";val context=object:android.content.ContextWrapper(app){override fun getSharedPreferences(name:String,mode:Int)=super.getSharedPreferences(namespace+name,mode)}
  val settings=SecureSettings(context);val foreground=AtomicInteger();settings.save("apiKey",credentials.s("apiKey"));settings.save("baseUrl",credentials.s("baseUrl"));for(role in listOf("tutor","archive"))settings.save("model.$role",credentials.s("model"));settings.save("tutor.thinking","off")
  val store=LearningStore(app,"018-live-${uid()}.sqlite");val provider=Provider(settings,foreground);val agents=Agents(app,store,provider,MemoryEngine(store),Library(app,store,provider,settings,foreground),foreground){_,_,_->}
  try{
   store.setSetting("learnPreferences","false");val q=store.put("question",payload(Question(title="自编接口验收",scope="math",scopeOrigin="user",transcription="原题 a=2，求 a 的平方")));val u=store.put("message",payload(Message(q.id,"user","参数改成 a=3","完整讲解")));store.updateConditions(q.id,u.id,"参数改成 a=3",false)
   repeat(45){store.put("message",payload(Message(q.id,if(it%2==0)"user"else "assistant","已完成的无关历史讨论。","完整讲解")))}
   assertTrue(agents.send(q.id,"只输出按当前生效条件计算的数值，不要输出解释。","完整讲解"));withTimeout(180000){while(agents.state.value.busy)delay(100)};assertEquals("",agents.state.value.error);assertTrue(agents.state.value.text.contains("9"));android.util.Log.i("Jieti018","PASS live long-context current conditions")
   val bitmap=Bitmap.createBitmap(900,700,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);val canvas=Canvas(bitmap);val paint=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.BLACK;textSize=40f};canvas.drawText("Formula y =",70f,120f,paint);canvas.drawText("1",430f,85f,paint);paint.strokeWidth=3f;canvas.drawLine(390f,100f,500f,100f,paint);canvas.drawText("x",420f,145f,paint);paint.textSize=24f;canvas.drawText("2",448f,125f,paint);paint.textSize=32f;canvas.drawText("Graph: horizontal t(s), vertical A(V)",70f,240f,paint);canvas.drawLine(120f,580f,780f,580f,paint);canvas.drawLine(120f,580f,120f,300f,paint);canvas.drawText("0",85f,610f,paint);canvas.drawText("t(s)",720f,625f,paint);canvas.drawText("A(V)",140f,310f,paint);canvas.drawLine(150f,380f,700f,550f,paint)
   val hash=store.addAsset(ByteArrayOutputStream().use{bitmap.compress(Bitmap.CompressFormat.PNG,100,it);bitmap.recycle();it.toByteArray()});val doc=store.importDocument(Document(title="自编公式图表.png",scope="test",assetIds=listOf(hash),mime="png"));Library(app,store,provider,settings,foreground).process(doc.id);val text=store.dao.chunks(doc.id,1).joinToString{it.text};assertTrue(text.contains("x"));assertTrue(text.contains("2"));assertTrue(text.contains("A")&&text.contains("t"));assertTrue(text.contains("V")&&text.contains("s"));assertEquals("verified",store.get(doc.id)!!.payload.s("quality"));android.util.Log.i("Jieti018","PASS live fraction, graph axes and units")
  }finally{agents.cancel();store.db.close();context.getSharedPreferences("protected_settings",0).edit().clear().commit()}
 }
 @Test fun uiSession()=runBlocking<Unit>{
  val ready=File(app.filesDir,"ui018-ready");val done=File(app.filesDir,"ui018-done");org.junit.Assume.assumeTrue(File(app.filesDir,"ui018-opt-in").exists());done.delete()
  val store=LearningStore(app,"018-ui-${uid()}.sqlite");val namespace="ui018-${uid()}-";val context=object:android.content.ContextWrapper(app){override fun getSharedPreferences(name:String,mode:Int)=super.getSharedPreferences(namespace+name,mode)};val settings=SecureSettings(context);val foreground=AtomicInteger();val fake=object:Provider(settings){override suspend fun chat(role:String,messages:JsonArray,tools:JsonArray?,stream:Boolean,priority:Boolean,jsonMode:Boolean,onDelta:(String)->Unit):Turn{onDelta("你圈选的是分母中的平方。先确认它属于整个分母，再检查变量范围。");return Turn("你圈选的是分母中的平方。先确认它属于整个分母，再检查变量范围。")}};val memory=MemoryEngine(store);val library=Library(app,store,fake,settings,foreground);val agents=Agents(app,store,fake,memory,library,foreground){_,_,_->}
  val oldCoach=app.coach;val oldSearch=app.questionSearch;val oldStore=app.store;val oldSettings=app.settings;val oldProvider=app.provider;val oldAgents=app.agents;val oldLibrary=app.library;val oldMemory=app.memory;val oldTheme=app.uiTheme.value;val oldColor=app.overlayColor.value
  try{
   val bitmap=Bitmap.createBitmap(1200,800,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);val canvas=Canvas(bitmap);val paint=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.BLACK;textSize=54f};canvas.drawText("Synthetic study sample",80f,100f,paint);canvas.drawText("y = 1 / x^2",100f,260f,paint);canvas.drawText("x > 0",100f,360f,paint);canvas.drawLine(120f,650f,1000f,650f,paint);canvas.drawLine(120f,650f,120f,450f,paint);val hash=store.addAsset(ByteArrayOutputStream().use{bitmap.compress(Bitmap.CompressFormat.PNG,100,it);bitmap.recycle();it.toByteArray()});val q=store.put("question",payload(Question(title="自编验收：公式定位与当前条件",scope="math",transcription="y=1/x^2，x>0",assetIds=listOf(hash),effectiveConditions="参数 a=3；沿用 x>0",conditionsOrigin="user",scopeOrigin="user")));store.put("message",payload(Message(q.id,"user","我想核对这个公式",assetIds=listOf(hash))));store.put("message",payload(Message(q.id,"assistant","先看分母的平方及自变量范围。")))
   for((index,value) in listOf("先给一个启动方向，等我尝试后再继续。","公式推导前先说明适用条件。","用图像帮助我理解变量之间的关系。").withIndex())store.put("memory",payload(MemoryItem("preference",if(index==2)"signals"else "math","ui-memory-$index",value,listOf(q.id),if(index==2)"inferred"else "explicit",if(index==2).6 else 1.0,now(),if(index==2)"candidate"else "active",false)))
   store.put("mastery",payload(MasterySnapshot("math","数列极限","developing",emptyList(),now())))
   app.coach=LearningCoach(app,store,fake,memory,library,QuestionSearch(settings)){_,_,_->};app.questionSearch=QuestionSearch(settings);app.store=store;app.settings=settings;app.provider=fake;app.agents=agents;app.library=library;app.memory=memory;app.uiTheme.value="light";app.overlayColor.value="#819A87";app.pendingFocus.value=null
   app.startActivity(android.content.Intent(app,MainActivity::class.java).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK or android.content.Intent.FLAG_ACTIVITY_CLEAR_TASK));ready.writeText("ready")
   withTimeout(600000){while(!done.exists())delay(200)}
   val focusMessages=store.all("message").filter{it.payload.s("focusRect").isNotBlank()};assertTrue("Circle selection should reach the actual send path",focusMessages.isNotEmpty());assertTrue(focusMessages.all{it.payload.s("focusAssetId").length==64&&it.payload.strings("assetIds").isNotEmpty()});android.util.Log.i("Jieti018","PASS observed UI crop-to-message provenance")
  }finally{agents.cancel();app.coach=oldCoach;app.questionSearch=oldSearch;app.store=oldStore;app.settings=oldSettings;app.provider=oldProvider;app.agents=oldAgents;app.library=oldLibrary;app.memory=oldMemory;app.uiTheme.value=oldTheme;app.overlayColor.value=oldColor;app.pendingFocus.value=null;ready.delete();done.delete();File(app.filesDir,"ui018-opt-in").delete();context.getSharedPreferences("protected_settings",0).edit().clear().commit();store.db.close();app.startActivity(android.content.Intent(app,MainActivity::class.java).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK or android.content.Intent.FLAG_ACTIVITY_CLEAR_TASK))}
 }
 @Test fun paletteAndFocusCoordinates(){val instrumentation=InstrumentationRegistry.getInstrumentation();instrumentation.runOnMainSync{val bitmap=Bitmap.createBitmap(400,400,Bitmap.Config.ARGB_8888);val view=FocusImageView(app,bitmap);view.layout(0,0,800,800);view.setZoom(2f);view.selecting=true;for((action,point)in listOf(MotionEvent.ACTION_DOWN to 300f,MotionEvent.ACTION_MOVE to 500f,MotionEvent.ACTION_UP to 500f)){val e=MotionEvent.obtain(1,2,action,point,point,0);view.onTouchEvent(e);e.recycle()};val rect=view.selectedPixels();assertEquals(175,rect.left);assertEquals(225,rect.right);bitmap.recycle()};for(p in OverlayColors.presets)assertTrue(OverlayColors.valid(p.hex));assertFalse(OverlayColors.valid("red"));fun lum(color:Int):Double{fun c(v:Int):Double{val x=v/255.0;return if(x<=.04045)x/12.92 else Math.pow((x+.055)/1.055,2.4)};return .2126*c(Color.red(color))+.7152*c(Color.green(color))+.0722*c(Color.blue(color))};for(dark in listOf(false,true))for(color in OverlayColors.presets.map{it.hex}+listOf("#000000","#FFFFFF","#FF0000"))for(background in listOf(Color.WHITE,Color.BLACK,Color.BLUE)){val bitmap=Bitmap.createBitmap(200,200,Bitmap.Config.ARGB_8888);bitmap.eraseColor(background);val glass=LiquidGlassDrawable(1f,30f,clear=true,frost={.94f},dark={dark},tint={OverlayColors.parse(color)});glass.setBounds(0,0,200,200);glass.draw(Canvas(bitmap));val fill=lum(bitmap.getPixel(100,100));val ink=lum(if(dark)0xFFE3E7DC.toInt()else 0xFF30392F.toInt());assertTrue("Palette contrast $color dark=$dark",(maxOf(fill,ink)+.05)/(minOf(fill,ink)+.05)>=4.5);bitmap.recycle()}}
}
